BEGIN ISOLATION LEVEL SERIALIZABLE;
-- check on-call doctors, then update
COMMIT;

SELECT id FROM email_jobs WHERE sent_at IS NULL
ORDER BY id LIMIT 10
FOR UPDATE SKIP LOCKED;

SELECT pid, pg_blocking_pids(pid) AS blocked_by, state, now() - xact_start AS open_for, left(query, 60)
FROM pg_stat_activity
WHERE cardinality(pg_blocking_pids(pid)) > 0 OR state = 'idle in transaction';

SELECT session_id, blocking_session_id, wait_type, wait_time, command
FROM sys.dm_exec_requests
WHERE blocking_session_id <> 0;
